/* In-app reminders, evaluated only when this page is open. No push or background delivery. */
(function(root,factory){'use strict';const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else api.mount(root)})(typeof globalThis!=='undefined'?globalThis:this,function(){'use strict';
function collect(engine,debts,preferences,today,locale){
 if(!Array.isArray(debts)||!preferences||typeof preferences!=='object'||Array.isArray(preferences))throw Error('Invalid reminder data');
 return debts.flatMap(debt=>{const p=Object.hasOwn(preferences,String(debt.id))?preferences[String(debt.id)]:{};if(!p||typeof p!=='object'||Array.isArray(p))throw Error('Invalid reminder preferences');const before=Number.isInteger(p.beforeDays)?p.beforeDays:3;return engine.schedule([{id:String(debt.id),name:String(debt.name),cutoffDay:p.cutoffDay,paymentDay:p.paymentDay??debt.due??null,cutoffEnabled:p.cutoffEnabled,paymentEnabled:p.paymentEnabled,paidThrough:p.paidThrough}],{today,offsets:p.sameDay===false?[before]:[before,0],daysAhead:0,locale})});
}
function mount(w){const host=w.document.querySelector('[aria-label="Recordatorios de obligaciones"]');if(!host||!w.DebtReminders)return;const section=w.document.createElement('div');section.className='notice';section.setAttribute('role','status');section.setAttribute('aria-live','polite');host.insertBefore(section,host.firstChild);
 function render(){const en=w.document.documentElement.lang==='en';section.replaceChildren();try{if(typeof storageLocked!=='undefined'&&storageLocked)throw Error('locked');const raw=w.localStorage.getItem('nando-recordatorios-v1'),prefs=raw===null?{}:JSON.parse(raw);const zone=Intl.DateTimeFormat().resolvedOptions().timeZone,today=w.DebtReminders.dateInZone(new Date(),zone);const current=typeof debts==='undefined'?[]:debts;const events=collect(w.DebtReminders,current,prefs,today,en?'en':'es');const title=w.document.createElement('strong');title.textContent=en?'Today’s reminders':'Avisos de hoy';section.append(title);const p=w.document.createElement('p');p.textContent=events.length?(en?'Review these dates with your lender.':'Confirma estas fechas con tu entidad.'):(en?'No reminders scheduled for today.':'No tienes avisos programados para hoy.');section.append(p);if(events.length){const ul=w.document.createElement('ul');for(const event of events){const li=w.document.createElement('li');li.textContent=w.DebtReminders.message(event,en?'en':'es');ul.append(li)}section.append(ul)}}catch(_){section.textContent=en?'Reminders cannot be checked. Your saved data was not changed.':'No se pudieron consultar los avisos. Tus datos guardados no se modificaron.'}}
 render();w.document.addEventListener('visibilitychange',()=>{if(w.document.visibilityState==='visible')render()});w.document.addEventListener('deudas:languagechange',render);w.addEventListener('storage',render);host.addEventListener('submit',()=>w.setTimeout(render,0));w.setInterval(()=>{if(w.document.visibilityState==='visible')render()},60000);const cards=w.document.getElementById('cards');if(cards&&w.MutationObserver){let queued=false;new w.MutationObserver(()=>{if(!queued){queued=true;w.setTimeout(()=>{queued=false;render()},0)}}).observe(cards,{childList:true,subtree:true,characterData:true})}const button=w.document.getElementById('rem-open');if(button)button.addEventListener('click',()=>w.setTimeout(render,0));
}
return Object.freeze({collect,mount});});
